  }

  // Check 2: No CORS protection
  if (!code.includes('cors')) {
    issues.push({
      severity: 'critical',
      category: 'CORS',
      description: 'CORS not configured. Exposes API to arbitrary origins.',
      recommendation: 'Install cors: npm install cors and configure with allowed origins'
    });
  }

  // Check 3: No rate limiting
  if (!code.includes('rateLimit')) {
    issues.push({
      severity: 'high',
      category: 'Rate Limiting',
      description: 'No rate limiting. Vulnerable to DoS attacks and abuse.',
      recommendation: 'Install express-rate-limit and add rate limiting middleware'
    });
  }

  // Check 4: Unvalidated input
  if (code.includes('req.query') || code.includes('req.params')) {
    hasInputValidation = false;
