    });
  }

  // Check 8: No environment variable validation
  if (!code.includes('process.env')) {
    observations.push({
      category: 'Environment Variables',
      description: 'No environment variables used in current implementation'
    });
  } else {
    issues.push({
      severity: 'high',
      category: 'Environment Variables',
      description: 'Environment variables referenced but app may need them.',
      recommendation: 'Add validation for required environment variables'
    });
  }

  // Check 9: Hardcoded sensitive data detection
  if (code.includes('.env')) {
