// Improved Express application with proper error handling and security practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const cors = require('cors');

// Initialize express app
const app = express();

// Security middleware
app.use(helmet()); // Set various HTTP headers for security
app.use(cors()); // Enable CORS with default settings (can be customized with options)

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later'
  },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all routes
app.use(limiter);

// Body parsers and sanitization
app.use(express.json({ limit: '10kb' })); // Limit payload to 10kb
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(mongoSanitize()); // Validate against NoSQL injection attempts
app.use(xss()); // Sanitize user input to prevent XSS attacks

// Validate object IDs using a custom middleware
const validateObjectId = (req, res, next) => {
  const id = req.params.id || req.body.id || req.query.id;
  if (id && !/^[0-9a-fA-F]{24}$/.test(id)) {
    return res.status(400).json({
      error: 'Invalid ID format. Must be a valid MongoDB ObjectId (24 hex characters)'
    });
  }
  next();
};

// Health check endpoint - always allowed (even at max rate limit)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate limit and offset query parameters
    const limit = parseInt(req.query.limit, 10) || 10;
    const offset = parseInt(req.query.offset, 10) || 0;

    // Validate numeric parameters
    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit. Must be a number between 1 and 100'
      });
    }

    if (isNaN(offset) || offset < 0) {
      return res.status(400).json({
        error: 'Invalid offset. Must be a non-negative number'
      });
    }

    // Mock user data - in production, this would come from your database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Implement pagination logic
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length,
        hasMore: offset + limit < users.length
      }
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// User endpoint with parameter validation and error handling
app.get('/users/:id', validateObjectId, (req, res) => {
  try {
    const { id } = req.params;

    // Validate ID format was already done by validateObjectId middleware

    // Mock user data - in production, query your database here
    const user = { id: 1, name: 'Alice', email: 'alice@example.com' };
    // user = await User.findById(id); // Real implementation

    if (!user) {
      return res.status(404).json({
        error: 'User not found'
      });
    }

    res.json(user);
  } catch (error) {
    // Log error in production instead of sending to client
    console.error('Error fetching user:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found'
  });
});

// Global error handler - must be the last middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  res.status(statusCode).json({
    error: err.message || 'Internal server error'
  });
});

// Graceful shutdown handler
const gracefulShutdown = (signal) => {
  console.log(`${signal} received. Shutting down gracefully...`);

  server.close(() => {
    console.log('Server closed. Exiting process.');
    process.exit(0);
  });

  // Force close after 10 seconds if graceful shutdown fails
  setTimeout(() => {
    console.error('Could not close connections in time, forcing shutdown...');
    process.exit(1);
  }, 10000);
};

// Add event listeners for graceful shutdown
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Start the server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Export app for testing
module.exports = app;

