// Security-enhanced Express application
// Includes input validation, error handling, and security best practices

const express = require('express');
const app = express();
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const Joi = require('joi');
const cookieParser = require('cookie-parser');

// Security middleware
app.use(helmet()); // Set various security HTTP headers
app.use(express.json({ limit: '10kb' })); // Parse JSON with size limit
app.use(express.urlencoded({ extended: false, limit: '10kb' }));
app.use(cookieParser());

// Rate limiting - protects against brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: 15 * 60 // seconds until retry
  },
  standardHeaders: true,
  legacyHeaders: false
});

// Apply limit to all routes
app.use(limiter);

// Custom error handler middleware
app.use((err, req, res, next) => {
  // Log error details (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Sanitize error response
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'development' ? err.message : 'Internal server error';

  res.status(statusCode).json({
    error: message,
    // Only expose in development
    ...(process.env.NODE_ENV === 'development' && {
      statusCode,
      stack: err.stack,
      path: req.path,
      method: req.method
    })
  });
});

// Health check endpoint - no validation needed
