// Security-enhanced Express application
// Includes input validation, error handling, and security best practices

const express = require('express');
const app = express();
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const Joi = require('joi');
const cookieParser = require('cookie-parser');

// Security middleware
app.use(helmet()); // Set various security HTTP headers
app.use(express.json({ limit: '10kb' })); // Parse JSON with size limit
app.use(express.urlencoded({ extended: false, limit: '10kb' }));
app.use(cookieParser());

// Rate limiting - protects against brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: 15 * 60 // seconds until retry
  },
  standardHeaders: true,
  legacyHeaders: false
});

// Apply limit to all routes
app.use(limiter);

// Configuration validation schema
const envSchema = Joi.object({
  NODE_ENV: Joi.string()
    .valid('development', 'test', 'production')
    .default('development'),
  PORT: Joi.number()
    .port()
    .required()
    .default(3000),
  // Optional: Add validation for other config if needed
  // DATABASE_URL: Joi.string().uri().optional(),
  // AWS_ACCESS_KEY_ID: Joi.string().trim().allow('').optional(),
  // AWS_SECRET_ACCESS_KEY: Joi.string().trim().allow('').optional(),
  // ANTHROPIC_API_KEY: Joi.string().trim().allow('').optional(),
  // STRIPE_SECRET_KEY: Joi.string().trim().allow('').optional(),
  // LOGFIRE_TOKEN: Joi.string().trim().allow('').optional(),
});

// Validate environment variables at startup
function validateEnvironment() {
  const { error, value } = envSchema.validate(process.env);
  if (error) {
    console.error('❌ Environment validation failed:', error.details);
    // Continue with defaults in development mode only
    if (process.env.NODE_ENV === 'development') {
      console.warn('⚠️ Running with default configuration due to validation warnings');
    }
  }
  return value;
}

const config = {
  nodeEnv: validateEnvironment().NODE_ENV || 'development',
  port: validateEnvironment().PORT || 3000,
};

// Custom error handler middleware
app.use((err, req, res, next) => {
  // Log error details (in production, use proper logging service)
  const logData = {
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    // Only log stack trace in development/test modes
    ...(config.nodeEnv !== 'production' && {
      stack: err.stack
    })
  };

  console.error('Error:', JSON.stringify(logData, null, 2));

  // Sanitize error response based on environment
  const statusCode = err.statusCode || 500;
  const message = config.nodeEnv !== 'development' ? 'Internal server error' : err.message;

  res.status(statusCode).json({
    error: message,
    statusCode,
    // Only expose in development/test modes
    ...(config.nodeEnv !== 'production' && {
      path: req.path,
      method: req.method
    })
  });
});

// Health check endpoint - minimal and safe
app.get('/health', (req, res) => {
  const healthResponse = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: Math.floor(process.uptime()),
    environment: config.nodeEnv,
    version: '1.0.0'
  };

  // Don't confirm inventory of services in production
  if (config.nodeEnv !== 'production' && process.env.DATABASE_URL) {
    healthResponse.database = { connected: true };
  }

  res.json(healthResponse);
});

// Validated users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const querySchema = Joi.object({
      page: Joi.number().integer().min(1).default(1),
      limit: Joi.number().integer().min(1).max(100).default(10),
      search: Joi.string().allow('').optional(),
    }).options({ stripUnknown: true });

    const { error, value } = querySchema.validate(req.query);
    if (error) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: error.details.map(d => d.message)
      });
    }

    // Use validated and sanitized values
    const { page, limit, search } = value;
    const offset = (page - 1) * limit;

    // Simulated user data - would query a database in production
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'admin' },
    ];

    // Only return user details relevant to the search (safety)
    const filteredUsers = search
      ? users.filter(user =>
          user.name.toLowerCase().includes(search.toLowerCase()) ||
          user.email.toLowerCase().includes(search.toLowerCase())
        )
      : users;

    // Pagination response with sanitized data
    const totalPages = Math.ceil(filteredUsers.length / limit);

    res.json({
      users: [filteredUsers.slice(offset, offset + limit)],
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        totalPages
      }
    });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// POST /users to create new user with input validation
app.post('/users', (req, res) => {
  try {
    // Validate request body
    const userSchema = Joi.object({
      name: Joi.string()
        .min(1)
        .max(100)
        .trim()
        .pattern(/^[a-zA-Z\s\-']$/)
        .required(),
      email: Joi.string()
        .email()
        .required(),
      role: Joi.string()
        .valid('user', 'admin', 'moderator')
        .default('user')
    });

    const { error, value } = userSchema.validate(req.body);
    if (error) {
      return res.status(400).json({
        error: 'Invalid user data',
        details: error.details.map(d => ({
          field: d.path.join('.'),
          message: d.message
        }))
      });
    }

    // Process validated data
    const newUser = {
      id: users.length + 1,
      name: value.name,
      email: value.email,
      role: value.role,
      createdAt: new Date().toISOString()
    };
    users.push(newUser);

    res.status(201).json({
      success: true,
      user: newUser
    });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

const users = [];

// PUT /users/:id to update user
app.put('/users/:id', (req, res) => {
  try {
    const userId = parseInt(req.params.id);
    if (isNaN(userId)) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    const userSchema = Joi.object({
      name: Joi.string()
        .min(1)
        .max(100)
        .trim()
        .pattern(/^[a-zA-Z\s\-']$/)
        .optional(),
      email: Joi.string().email().optional(),
      role: Joi.string().valid('user', 'admin', 'moderator').optional()
    });

    const { error, value } = userSchema.validate(req.body);
    if (error) {
      return res.status(400).json({
        error: 'Invalid update data',
        details: error.details.map(d => ({
          field: d.path.join('.'),
          message: d.message
        }))
      });
    }

    const userIndex = users.findIndex(u => u.id === userId);
    if (userIndex === -1) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Update with validated data only
    users[userIndex] = {
      ...users[userIndex],
      ...value,
      updatedAt: new Date().toISOString()
    };

    res.json({
      success: true,
      user: users[userIndex]
    });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// DELETE /users/:id to remove a user
app.delete('/users/:id', (req, res) => {
  try {
    const userId = parseInt(req.params.id);
    if (isNaN(userId)) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    const userIndex = users.findIndex(u => u.id === userId);
    if (userIndex === -1) {
      return res.status(404).json({ error: 'User not found' });
    }

    const removedUser = users.splice(userIndex, 1)[0];

    res.json({
      success: true,
      message: `User "${removedUser.name}" deleted`,
      userId: removedUser.id
    });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// Rate limiter specifically for POST/PUT/DELETE routes
const mutationLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 30, // limit to 30 mutations per 15 minutes
  message: {
    error: 'Too many mutation requests. Please reduce your activity.',
    retryAfter: 15 * 60
  },
  standardHeaders: true,
  legacyHeaders: false
});

// Apply to mutation routes
app.use('/users', mutationLimiter);

// 404 handler
app.use((req, res) => {
  console.warn(`404 - Path not found: ${req.method} ${req.path}`);
  res.status(404).json({
    error: 'Endpoint not found',
    path: req.path,
    method: req.method
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log(`Graceful shutdown triggered. Environment: ${config.nodeEnv}`);
  app.close(() => {
    console.log('Server closed gracefully');
    process.exit(0);
  });
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Don't exit in test/development to allow debugging if needed
  if (config.nodeEnv !== 'test') {
    // In production, send to error tracking service
    process.exit(1);
  }
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Don't exit in test/development to allow debugging if needed
  if (config.nodeEnv !== 'test') {
    // In production, send to error tracking service
  }
});

// Start server with error handling
app.listen(config.port, (err) => {
  if (err) {
    console.error('Failed to start server:', err);
    process.exit(1);
  }
  console.log(`✓ Server running on port ${config.port} in ${config.nodeEnv} mode`);
});

module.exports = app;

