# Security Improvements for app.js

## Review Status: POOR - Multiple Critical Vulnerabilities Found

This code has several security issues that need immediate attention.

---

## 🔴 Critical Issues

### 1. Missing CORS Configuration
**Risk:** Allows Cross-Origin Resource Sharing from any origin, potentially exposing sensitive data.

**Current Code:**
```javascript
const express = require('express');
const app = express();
```

**Problem:** Express app has default CORS enabled for all origins.

**Fix:**
```javascript
const cors = require('cors');

// Restrict CORS to only your frontend domains
const corsOptions = {
  origin: 'https://your-frontend-domain.com',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true
};

app.use(cors(corsOptions));
```

Or disable completely if frontend needs to call the API:
```javascript
// app.use(cors(corsOptions)); // Or check dynamically
```

---

### 2. No Input Validation on Routes
**Risk:** Path Traversal, XSS Protection needed, Malformed requests.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Problem:** No validation of request parameters or body data.

**Fix:**
```javascript
// Add validation middleware
const { body, param, validationResult } = require('express-validator');

const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      errors: errors.array()
    });
  }
  next();
};

app.get(
  '/users',
  [
    // Validate request query parameters
    param('page')
      .optional()
      .isInt({ min: 1 })
      .toInt(),
    param('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
  ],
  validate,
  (req, res) => {
    // Safe to use validated params
    const page = parseInt(req.query.page) || 1;
    const limit = Math.min(parseInt(req.query.limit) || 20, 100);

    // ... rest of your code
  }
);
```

---

### 3. No Rate Limiting
**Risk:** DoS attacks, Brute force exposure of API endpoints.

**Problem:** No protection against excessive API calls.

**Fix:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  message: {
    status: 'error',
    message: 'Too many requests, please try again later.'
  }
});

// Apply limiter globally
app.use(limiter);

// Apply to specific routes
const apiLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 1000, // 1000 requests per hour
  skipSuccessfulRequests: true
});

app.use('/api', apiLimiter);
```

---

### 4. Missing Helmet.js Security Headers
**Risk:** Exposed to CORS attacks, XSS, information disclosure.

**Problem:** No security headers configured.

**Fix:**
```javascript
const helmet = require('helmet');

// Apply security headers
app.use(helmet());
// Or customize headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"], // Adjust based on your needs
      imgSrc: ["'self'", 'data:', 'https:']
    }
  }
}));
```

---

### 5. No Input Sanitization
**Risk:** XSS attacks through user input.

**Problem:** No sanitization of user input.

**Fix:**
```javascript
const xss = require('xss-clean');

// Sanitize input data to prevent XSS
app.use(xss());

// If using middleware like multer for file uploads
const sanitizeOptions = {
  replaceWith: ' ', // Replace special chars with spaces
  resetOnLevel: false
};
const sanitize = require('../middleware/sanitize');
app.use(sanitize(sanitizeOptions));
```

---

## 🟡 High Priority Issues

### 6. No Custom Error Handler
**Risk:** Stack traces exposed to clients, inconsistent error responses.

**Problem:** Express defaults used for errors.

**Fix:**
```javascript
// Centralized error handling
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err);

  res.status(err.statusCode || 500).json({
    status: 'error',
    message: process.env.NODE_ENV === 'production'
      ? 'Something went wrong'
      : err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
};

// Zod validation errors
const handleZodError = (err, req, res, next) => {
  if (err.name === 'ZodError') {
    res.status(400).json({
      status: 'error',
      message: 'Invalid request data',
      errors: err.errors
    });
  }
  next(err);
};

// Async error wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Wrap all handlers
app.get('/users', asyncHandler(async (req, res, next) => {
  // Your code here
}));

// Add error middleware
app.use(asyncHandler((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    status: 'error',
    message: 'Internal server error'
  });
}));

// Always call next(errorHandler) in error routes
```

---

### 7. No Authentication/Authorization
**Risk:** Authentication bypass, unauthorized data access.

**Problem:** Open endpoints - no authentication required.

**Fix:**
```javascript
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

// JWT Middleware
const authenticate = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');

  if (!token) {
    return res.status(401).json({
      status: 'error',
      message: 'Access denied. No token provided.'
    });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(401).json({
      status: 'error',
      message: 'Invalid token.'
    });
  }
};

// Role-based authorization
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!roles.includes(req.user.role)) {
      return res.status(403).json({
        status: 'error',
        message: 'Not authorized to access this resource'
      });
    }
    next();
  };
};

// Usage
app.get('/admin/users', authenticate, authorize('admin'), (req, res, next) => {
  // Only admin can access
});

app.post('/users', authenticate, validateUserCreation, asyncHandler(async (req, res) => {
  // Secure user creation endpoint
}));
```

---

### 8. Missing Environment Variables Validation
**Risk:** Application crash due to missing config, security issues.

**Problem:** No validation of environment variables.

**Fix:**
```javascript
const dotenv = require('dotenv');

// Load and validate environment variables
dotenv.config();

const validateEnv = () => {
  const required = {
    PORT: process.env.PORT || '3000',
    NODE_ENV: process.env.NODE_ENV || 'development',
    // Add all required variables
  };

  // Validate required environment variables
  const missing = Object.keys(required).filter(key => !required[key]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  return required;
};

try {
  const env = validateEnv();
  console.log('Environment validated successfully');
} catch (error) {
  console.error('Environment validation failed:', error.message);
  process.exit(1);
}

// Use validated values
const PORT = process.env.PORT || 3000;
```

---

### 9. No Input Sanitization for Query Parameters
**Risk:** Path traversal, NoSQL injection.

**Problem:** Query parameters not sanitized.

**Fix:**
```javascript
// Sanitize route parameters
app.get(
  '/users/:id',
  [
    param('id')
      .isMongoId()
      .withMessage('Invalid user ID format')
  ],
  validate,
  asyncHandler(async (req, res) => {
    // ID is now validated as a valid MongoDB ObjectId
    const { id } = req.params;
    const user = await User.findById(id);

    if (!user) {
      throw new NotFoundError('User not found');
    }

    res.json(user);
  })
);

// Sanitize search queries
app.get(
  '/search',
  [
    query('q')
      .isLength({ min: 3, max: 100 })
      .trim()
      .escape() // Prevent XSS
      .normalizeEmail(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
  ],
  validate,
  asyncHandler(async (req, res) => {
    const query = req.query.q;
    // Safe to use query parameter
    const results = await search(query);
    res.json(results);
  })
);
```

---

### 10. Insecure Secrets Logging
**Risk:** Security exposure through error logs.

**Problem:** Sensitive data could be logged.

**Fix:**
```javascript
// Redact sensitive data in error logs
const morgan = require('morgan');
const winston = require('winston');
const { format } = require('winston');

const redactSensitiveData = (req, res, next) => {
  // Store original res.json
  const originalJson = res.json.bind(res);
  res.json = (data) => {
    // Deep clone to avoid modifying original
    const clonedData = JSON.parse(JSON.stringify(data));
    // Add isLoggable: false header
    res.setHeader('X-Is-Loggable', 'false');
    return originalJson(clonedData);
  };
  next();
};

// Add to app.use
app.use(redactSensitiveData);

// Security-aware logger
const logger = winston.createLogger({
  level: 'info',
  format: format.combine(
    format.timestamp(),
    format.errors({ stack: true }),
    format.json()
  ),
  transports: [
    new winston.transports.File({
      filename: 'error.log',
      level: 'error',
      format: format.((info) => {
        // Redact sensitive data before logging
        const confidential = [
          'password', 'secret', 'token', 'apiKey', 'accessToken', 'refreshToken',
          'cookie', 'sessionid', 'mongodbid'
        ];

        return confidential.reduce((obj, key) => {
          if (obj[key]) {
            obj[key] = '[REDACTED]';
          }
          return obj;
        }, { ...info });
      }),
    })
  ]
});
```

---

## 🟢 Recommended Libraries

