// Improved application with security best practices
// This version focuses on error handling, input validation, and security
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { validationResult } = require('express-validator');
const expressValidator = require('express-validator');

// Centralized error handler
const errorHandler = (err, req, res, next) => {
  console.error('Error occurred:', err);

  res.status(err.statusCode || 500).json({
    status: 'error',
    message: process.env.NODE_ENV === 'production'
      ? 'An internal server error occurred'
      : err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
};

// Input validation middleware
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      errors: errors.array()
    });
  }
  next();
};

// Security configuration
const corsOptions = {
  origin: (origin, callback) => {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:5173';
    const isOriginAllowed = allowedOrigins.includes(origin) || !origin;

    if (isOriginAllowed || process.env.NODE_ENV === 'development') {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400
};

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    status: 'error',
    message: 'Too many requests, please try again later.',
    retryAfter: 900 // seconds
  }
});

const app = express();

// Middleware setup
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(helmet()); // Security headers
app.use(cors(corsOptions)); // CORS configuration
app.use(limiter); // Rate limiting

// Health check endpoint with input validation
app.get(
  '/health',
  [],
  validate,
  (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  }
);

// Users endpoint with input validation
app.get(
  '/users',
  [
    // Validate query parameters
    expressValidator.query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt(),
    expressValidator.query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt(),
    expressValidator.query('sortBy')
      .optional()
      .isIn(['name', 'email', 'id'])
      .withMessage('Invalid sort field')
  ],
  validate,
  (req, res) => {
    // Use validated parameters (safe from injection)
    const page = parseInt(req.query.page) || 1;
    const limit = Math.min(parseInt(req.query.limit) || 20, 100);
    const sortBy = req.query.sortBy || 'id';

    // Simulate paginated data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Validate sortBy to prevent injection
    const validSortFields = ['id', 'name', 'email', 'createdAt'];
    const fieldToSort = validSortFields.includes(sortBy) ? sortBy : 'id';

    const sortedUsers = allUsers.sort((a, b) => {
      if (a[fieldToSort] > b[fieldToSort]) return 1;
      if (a[fieldToSort] < b[fieldToSort]) return -1;
      return 0;
    });

    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = sortedUsers.slice(startIndex, endIndex);

    res.json({
      status: 'success',
      page,
      limit,
      totalPages: Math.ceil(allUsers.length / limit),
      totalCount: allUsers.length,
      data: paginatedUsers
    });
  }
);

// Error handling middleware (must be last)
app.use(errorHandler);

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  process.exit(0);
});

module.exports = app;

