const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const cors = require('cors');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Helmet: Sets various HTTP headers for security
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

// Rate limiting: Protect against brute force/DDoS attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes except /health
app.use('/api/', apiLimiter);

// Rate limiting for /health (keep it more permissive for monitoring)
const healthLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 60, // 60 requests per minute
  message: {
    error: 'Too health check requests, please slow down.',
  },
});
app.get('/health', healthLimiter, (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// CORS: Configure allowed origins
app.use(cors({
  origin: process.env.CORS_ORIGINS ? process.env.CORS_ORIGINS.split(',') : 'http://localhost:3001',
  credentials: true,
  optionsSuccessStatus: 200,
}));

// Input sanitization
app.use(xss()); // Prevent XSS attacks
app.use(mongoSanitize()); // Prevent NoSQL injection

// Request size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON payload
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded data

// ==================== ROUTES ====================

// Add input validation middleware
const validateQueryParam = (param, pattern) => {
  return (req, res, next) => {
    if (param in req.query && !pattern.test(req.query[param])) {
      return res.status(400).json({ error: 'Invalid query parameter format' });
    }
    next();
  };
};

app.get('/users', validateQueryParam('page', /^\d+$/), (req, res) => {
  // Validate page number
  const page = parseInt(req.query.page) || 1;
  const limit = Math.min(Math.max(parseInt(req.query.limit) || 10, 1), 100); // Cap at 100

