// Improved application with security best practices
const express = require('express');
const app = express();
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const xss = require('xss-clean'); // XSS protection
const mongoSanitize = require('express-mongo-sanitize'); // NoSQL injection prevention

// Security middleware
app.use(helmet()); // Set various HTTP headers for security
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(mongoSanitize()); // Sanitize data against NoSQL injection
app.use(xss()); // Prevent XSS attacks

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Request validation middleware
const validateRequest = (req, res, next) => {
  try {
    // Basic schema validation
    if (req.body) {
      Object.keys(req.body).forEach(key => {
        if (typeof req.body[key] === 'string') {
          // Trim whitespace
          req.body[key] = req.body[key].trim();
          // Check for empty controllers injection attempts
          if (req.body[key].length > 1000) {
            throw new Error(`Field '${key}' exceeds maximum length of 1000 characters`);
          }
          // Check for script tags
          if (/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi.test(req.body[key])) {
            throw new Error(`Field '${key}' contains invalid characters`);
          }
        }
      });
    }
    next();
  } catch (error) {
    res.status(400).json({
      error: 'Invalid request',
      message: error.message
    });
  }
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
