'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const app = express();

// ===== SECURITY MIDDLEWARE =====

// Helmet: Set security-related HTTP headers
app.use(helmet({
  contentSecurityPolicy: false, // Disabled for simplicity, configure per route if needed
  crossOriginEmbedderPolicy: false,
  crossOriginOpenerPolicy: false,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use(limiter);

// JSON parsing with size limits
app.use(express.json({
  limit: '1mb',
  verify: (req, res, buf) => {
    // Optionally detect malicious JSON payloads
    if (buf && buf.length > 1000000) {
      console.error('JSON payload size exceeds limit');
    }
  }
}));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// ===== REQUEST LOGGING =====
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);
  next();
});

// ===== ERROR HANDLING MIDDLEWARE =====

// Handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Handle general errors
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Handle validation errors from express-validator
  if (err.array) {
    return res.status(400).json({
      success: false,
      errors: err.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }

  // Handle JWT authentication errors
  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      success: false,
      message: 'Invalid or expired token'
    });
  }

  // Handle generic errors
  res.status(err.status || 500).json({
    success: false,
    message: process.env.NODE_ENV === 'development' ? err.message : 'Internal server error'
  });
});

// ===== ROUTES =====

// Health check endpoint (should be protected)
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error'
    });
  }
});

// Users list endpoint with input validation
app.get('/users', [
  // Validate query parameters
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('search')
    .optional()
    .trim()
    .escape()
    .isLength({ max: 100 })
    .withMessage('Search query too long'),
  handleValidationErrors
], (req, res) => {
  try {
    const { page = 1, limit = 10, search } = req.query;

    // Parse and validate pagination parameters
    const pg = Math.max(1, parseInt(page) || 1);
    const lim = Math.min(100, Math.max(1, parseInt(limit) || 10));

    // In a real app, this would fetch from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple search if provided
    const searchLower = search ? search.toLowerCase() : '';
    const filteredUsers = searchLower
      ? users.filter(u =>
          u.name.toLowerCase().includes(searchLower) ||
          u.email.toLowerCase().includes(searchLower)
        )
      : users;

    res.json({
      success: true,
      data: filteredUsers.slice(0, lim),
      pagination: {
        page: pg,
        limit: lim,
        total: filteredUsers.length
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    throw error;
  }
});

// User detail endpoint with input validation
app.get('/users/:id', [
  // Validate ID parameter
  query('id')
    .notEmpty()
    .escape()
    .isInt()
    .withMessage('Invalid user ID'),
  // Validate optional query parameters
  query('includeDetails')
    .optional()
    .isBoolean()
    .withMessage('Include details must be a boolean'),
  handleValidationErrors
], (req, res) => {
  try {
    const { id } = req.params;

    // Validate user ID
    const userId = parseInt(id);
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({
        success: false,
        message: 'Invalid user ID'
      });
    }

    // In a real app, this would fetch from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        success: false,
        message: 'User not found'
      });
    }

    res.json({
      success: true,
      data: user
    });
  } catch (error) {
    console.error('Error fetching user:', error);
    throw error;
  }
});

// POST endpoint for creating users
app.post('/users', [
  // Validate email format
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .escape(),
  body('email')
    .trim()
    .notEmpty()
    .withMessage('Email is required')
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail()
    .isLength({ max: 255 })
    .withMessage('Email too long'),
  // Optional additional fields
  body('age')
    .optional()
    .isInt({ min: 1, max: 150 })
    .withMessage('Age must be a positive integer')
    .isNumeric(),
  handleValidationErrors
], (req, res) => {
  try {
    // Create user (in real app, this would save to database)
    const newUser = {
      id: Date.now(), // In real app, would get from database
      name: req.body.name,
      email: req.body.email,
      age: req.body.age || null
    };

    res.status(201).json({
      success: true,
      data: newUser,
      message: 'User created successfully'
    });
  } catch (error) {
    console.error('Error creating user:', error);
    throw error;
  }
});

// ===== 404 HANDLER =====
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Route not found'
  });
});

// ===== START SERVER =====
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

